// La RPC devuelve el jsonb directo. PostgREST a veces lo entrega envuelto en
// un array de un elemento, asi que se normaliza antes de leerlo.
let r = $json;
if (Array.isArray(r)) { r = r[0] || {}; }
if (r && r.data && !r.nuevos_24h && !r.urgentes) { r = r.data; }
const nuevos = Array.isArray(r.nuevos_24h) ? r.nuevos_24h : [];
const urgentes = Array.isArray(r.urgentes) ? r.urgentes : [];
const reincidentes = Number(r.reincidentes) || 0;
// coalesce del lado del SQL devuelve null cuando no hay conversaciones.
const enSilencio = r.en_silencio === true;
// Si no hay NADA que contar, no se manda correo. Un aviso diario que llega
// aunque no haya novedad se ignora en una semana.
const enviar = nuevos.length > 0 || urgentes.length > 0 || enSilencio;
const esc = function (s) { return String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const lista = function (arr) { return arr.map(function (v) {
  return '<li><b>' + v.preguntas + '&times;</b> ' + esc(v.titulo) + '</li>'; }).join(''); };
const partes = [];
if (enSilencio) { partes.push('<p style="color:#b00"><b>El registro de vacios parece roto.</b> El bot reporto preguntas sin respuesta pero no se registro ninguna. Revisa la rama de registro del workflow de n8n.</p>'); }
if (urgentes.length) { partes.push('<h3>Urgentes (cruzaron el umbral)</h3><ul>' + lista(urgentes) + '</ul>'); }
if (nuevos.length) { partes.push('<h3>Nuevos en las ultimas 24 horas</h3><ul>' + lista(nuevos) + '</ul>'); }
if (reincidentes > 0) { partes.push('<p>' + reincidentes + ' vacio(s) <b>resueltos que siguen preguntandose</b>: el contenido existe y el bot no lo esta recuperando. Revisa que esas lecciones esten activas y con el embedding al dia.</p>'); }
const subject = urgentes.length
  ? ('BolBot: ' + urgentes.length + ' vacio(s) urgente(s) por atender')
  : (enSilencio ? 'BolBot: el registro de vacios parece roto'
                : ('BolBot: ' + nuevos.length + ' vacio(s) nuevo(s)'));
const html = '<div style="font-family:Helvetica,Arial,sans-serif;font-size:14px">'
  + '<h2>Bandeja de vacios de BolBot</h2>' + partes.join('')
  + '<p style="color:#666;font-size:12px">Abre el admin &rarr; Vacios del bot para atenderlos.</p></div>';
return [{ json: { enviar: enviar, subject: subject, html: html } }];
